def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    recent_len = min(10, n)
    start_recent = n - recent_len
    my_last, opp_last = history[-1]

    opp_d = 0
    recent_d = 0
    my_d = 0
    recent_my_d = 0
    unprov = 0
    punish = 0
    we_c = 0
    coop_we_c = 0
    recent_we_c = 0
    recent_coop = 0
    last2_opp_d = n >= 2 and history[-1][1] == 'D' and history[-2][1] == 'D'

    for i, (m, o) in enumerate(history):
        if m == 'C':
            we_c += 1
            if o == 'C':
                coop_we_c += 1
        else:
            my_d += 1

        if o == 'D':
            opp_d += 1
            if i == 0:
                unprov += 1
            elif history[i - 1][0] == 'C':
                unprov += 1
            else:
                punish += 1

        if i >= start_recent:
            if m == 'C':
                recent_we_c += 1
                if o == 'C':
                    recent_coop += 1
            else:
                recent_my_d += 1
            if o == 'D':
                recent_d += 1

    if we_c >= 5 and coop_we_c * 3 <= we_c:
        return 'D'
    if recent_we_c >= 3 and recent_coop * 3 <= recent_we_c and recent_d >= 2:
        return 'D'
    if recent_d >= 5 and recent_my_d <= 2:
        return 'D'
    if opp_d >= 3 and opp_d * 2 >= n and unprov >= 3:
        return 'D'

    if n == 98:
        if opp_last == 'D' or recent_d >= 2 or opp_d >= 4:
            return 'D'
        if my_d == 0:
            return 'D' if rng.random() < 0.65 else 'C'
        if punish == 0 and opp_d <= 2 and recent_d <= 1:
            return 'D'
        return 'D' if rng.random() < 0.25 else 'C'

    if opp_last == 'D':
        if last2_opp_d:
            return 'D'
        if my_last == 'D':
            if recent_d >= 3 or unprov >= 3 or (opp_d >= 3 and opp_d * 2 >= n):
                return 'D'
            return 'C' if rng.random() < 0.75 else 'D'
        if recent_d == 1 and unprov <= 1 and n >= 20 and we_c > 15 and coop_we_c >= we_c - 1:
            return 'C' if rng.random() < 0.25 else 'D'
        return 'D'

    if recent_we_c >= 3 and recent_coop == 0 and recent_d >= 3:
        return 'D'

    if 5 <= n < 97:
        coopish = opp_d <= max(1, n // 3) and recent_d <= 2
        if coopish and recent_my_d <= 1 and my_last == 'C' and opp_last == 'C':
            if n == 10 or n == 30 or n == 60 or n == 80 or n == 90 or rng.random() < 0.02:
                return 'D'

    return 'C'
